<div class="event-admin-heading"><div><a class="event-back" href="<?= site_url('pengelola/kegiatan') ?>">← Semua kegiatan</a><span class="admin-overline">STUDIO HALAMAN DAN FORMULIR</span><h1><?= html_escape($event['title']) ?></h1><p>Susun komponen dengan menarik pegangan, lalu atur pertanyaan pendaftaran.</p></div><?php if($event['status']==='published'): ?><a class="event-primary secondary" href="<?= site_url('kegiatan/'.$event['slug']) ?>" target="_blank" rel="noopener">Lihat halaman ↗</a><?php endif; ?></div>
