<form method="post" id="studio-form" action="<?= site_url('pengelola/kegiatan/'.$event['id'].'/studio') ?>"><input type="hidden" name="<?= $this->security->get_csrf_token_name() ?>" value="<?= $this->security->get_csrf_hash() ?>"><input type="hidden" name="design_json" id="studio-design-json"><input type="hidden" name="fields_json" id="studio-fields-json">
<div class="studio-grid"><div><section class="event-admin-card"><div class="event-section-head"><div><span class="admin-overline">TAMPILAN PUBLIK</span><h2>Komponen halaman</h2></div></div><p class="studio-help">Judul kegiatan selalu tampil di atas. Atur urutan bagian di bawahnya.</p><label class="event-field studio-theme">Warna halaman<select id="studio-theme"><option value="ocean">Biru laut</option><option value="sage">Hijau lembut</option><option value="sunset">Hangat</option></select></label><div id="studio-blocks" class="studio-stack"></div><div class="studio-add"><button type="button" data-add-block="summary">+ Ringkasan</button><button type="button" data-add-block="facts">+ Jadwal dan lokasi</button><button type="button" data-add-block="body">+ Deskripsi</button><button type="button" data-add-block="image">+ Gambar utama</button><button type="button" data-add-block="note">+ Catatan khusus</button></div></section><section class="event-admin-card"><div class="event-section-head"><div><span class="admin-overline">PENDAFTARAN</span><h2>Formulir peserta</h2></div></div><p class="studio-help">Nama dan nomor HP diambil dari akun pengunjung. Pertanyaan tambahan di bawah ini disimpan per versi.</p><div id="studio-fields" class="studio-stack"></div><div class="studio-add"><button type="button" id="studio-add-field">+ Tambah pertanyaan</button></div></section></div><aside class="studio-preview-wrap"><div class="event-admin-card studio-preview"><span class="admin-overline">PRATINJAU LANGSUNG</span><div id="studio-preview" class="studio-preview-page"></div></div></aside></div><div class="studio-save"><a href="<?= site_url('pengelola/kegiatan') ?>">Kembali</a><button type="submit" class="event-primary">Simpan versi baru</button></div></form>
<script id="studio-initial" type="application/json"><?= json_encode($initial,JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?></script>
<script>
(function(){
var data=JSON.parse(document.getElementById('studio-initial').textContent),design=data.design||{},blocks=Array.isArray(design.blocks)?design.blocks:[],fields=Array.isArray(data.fields)?data.fields:[];
var theme=document.getElementById('studio-theme'),blocksBox=document.getElementById('studio-blocks'),fieldsBox=document.getElementById('studio-fields'),preview=document.getElementById('studio-preview');
var names={summary:'Ringkasan kegiatan',facts:'Jadwal dan lokasi',body:'Deskripsi kegiatan',image:'Gambar utama',note:'Catatan khusus'};
theme.value=['ocean','sage','sunset'].indexOf(design.theme)>=0?design.theme:'ocean';
fields=fields.map(function(f){return {key:f.key||f.field_key||('field_'+Math.random().toString(36).slice(2,12)),label:f.label||'',type:f.type||f.field_type||'text',required:!!(f.required||Number(f.is_required)),options:Array.isArray(f.options)?f.options:[]}});
function el(tag,cls,text){var n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n}
function button(label,action){var b=el('button','studio-small-button',label);b.type='button';b.addEventListener('click',action);return b}
function reorder(array,index,direction){var next=index+direction;if(next<0||next>=array.length)return;var item=array.splice(index,1)[0];array.splice(next,0,item);render()}
function render(){renderBlocks();renderFields();renderPreview()}
function renderBlocks(){blocksBox.replaceChildren();blocks.forEach(function(block,index){var card=el('div','studio-item');card.dataset.index=index;var top=el('div','studio-item-top');var handle=el('span','studio-drag','⋮⋮');handle.draggable=true;handle.title='Tarik untuk mengubah urutan';handle.addEventListener('dragstart',function(e){e.dataTransfer.setData('text/plain','block:'+index)});top.append(handle,el('strong','',names[block.type]||block.type));var actions=el('div','studio-item-actions');actions.append(button('↑',function(){reorder(blocks,index,-1)}),button('↓',function(){reorder(blocks,index,1)}),button('Hapus',function(){blocks.splice(index,1);render()}));top.append(actions);card.append(top);if(block.type==='note'){var h=el('input','studio-input');h.placeholder='Judul catatan';h.maxLength=120;h.value=block.heading||'';h.addEventListener('input',function(){block.heading=h.value;renderPreview()});var t=el('textarea','studio-input');t.placeholder='Isi catatan';t.rows=3;t.maxLength=1200;t.value=block.text||'';t.addEventListener('input',function(){block.text=t.value;renderPreview()});card.append(h,t)}else card.append(el('p','studio-item-help',block.type==='image'?'Menggunakan gambar utama yang diunggah di halaman Ubah kegiatan.':'Menggunakan informasi dari halaman Ubah kegiatan.'));card.addEventListener('dragover',function(e){e.preventDefault()});card.addEventListener('drop',function(e){e.preventDefault();var value=e.dataTransfer.getData('text/plain');if(value.indexOf('block:')!==0)return;var from=Number(value.slice(6));if(from===index||!Number.isInteger(from)||from<0||from>=blocks.length)return;var item=blocks.splice(from,1)[0];blocks.splice(index,0,item);render()});blocksBox.append(card)})}
function renderFields(){fieldsBox.replaceChildren();fields.forEach(function(field,index){var card=el('div','studio-item');var top=el('div','studio-item-top');var handle=el('span','studio-drag','⋮⋮');handle.draggable=true;handle.title='Tarik untuk mengubah urutan';handle.addEventListener('dragstart',function(e){e.dataTransfer.setData('text/plain','field:'+index)});top.append(handle,el('strong','','Pertanyaan '+(index+1)));var actions=el('div','studio-item-actions');actions.append(button('↑',function(){reorder(fields,index,-1)}),button('↓',function(){reorder(fields,index,1)}),button('Hapus',function(){fields.splice(index,1);render()}));top.append(actions);card.append(top);var grid=el('div','studio-field-grid'),label=el('input','studio-input');label.placeholder='Pertanyaan untuk peserta';label.maxLength=160;label.value=field.label;label.addEventListener('input',function(){field.label=label.value;renderPreview()});var type=el('select','studio-input');[['text','Jawaban singkat'],['textarea','Jawaban panjang'],['select','Pilihan'],['number','Angka'],['date','Tanggal'],['checkbox','Persetujuan']].forEach(function(option){var o=el('option','',option[1]);o.value=option[0];type.append(o)});type.value=field.type;var options=el('input','studio-input');options.placeholder='Pilihan, pisahkan dengan koma';options.value=(field.options||[]).join(', ');options.hidden=field.type!=='select';options.addEventListener('input',function(){field.options=options.value.split(',').map(function(x){return x.trim()}).filter(Boolean);renderPreview()});type.addEventListener('change',function(){field.type=type.value;options.hidden=type.value!=='select';renderPreview()});var required=el('label','studio-required'),check=el('input');check.type='checkbox';check.checked=field.required;check.addEventListener('change',function(){field.required=check.checked;renderPreview()});required.append(check,document.createTextNode(' Wajib diisi'));grid.append(label,type,options,required);card.append(grid);card.addEventListener('dragover',function(e){e.preventDefault()});card.addEventListener('drop',function(e){e.preventDefault();var value=e.dataTransfer.getData('text/plain');if(value.indexOf('field:')!==0)return;var from=Number(value.slice(6));if(from===index||!Number.isInteger(from)||from<0||from>=fields.length)return;var item=fields.splice(from,1)[0];fields.splice(index,0,item);render()});fieldsBox.append(card)})}
function renderPreview(){preview.className='studio-preview-page theme-'+theme.value;preview.replaceChildren();preview.append(el('small','','KEGIATAN UMKM'),el('h3','',<?= json_encode($event['title'],JSON_UNESCAPED_UNICODE|JSON_HEX_TAG) ?>));blocks.forEach(function(block){var box=el('div','studio-preview-block');box.append(el('strong','',block.type==='note'?(block.heading||'Catatan khusus'):names[block.type]));if(block.type==='note'&&block.text)box.append(el('p','',block.text));preview.append(box)});if(fields.length){var form=el('div','studio-preview-form');form.append(el('strong','','Formulir peserta'));fields.forEach(function(f){form.append(el('span','',(f.label||'Pertanyaan')+(f.required?' *':'')))});preview.append(form)}}
document.querySelectorAll('[data-add-block]').forEach(function(b){b.addEventListener('click',function(){var type=b.dataset.addBlock;if(type!=='note'&&blocks.some(function(x){return x.type===type}))return;blocks.push(type==='note'?{type:'note',heading:'Informasi tambahan',text:''}:{type:type});render()})});document.getElementById('studio-add-field').addEventListener('click',function(){fields.push({key:'field_'+Date.now().toString(36)+Math.random().toString(36).slice(2,6),label:'',type:'text',required:false,options:[]});render()});theme.addEventListener('change',renderPreview);document.getElementById('studio-form').addEventListener('submit',function(){document.getElementById('studio-design-json').value=JSON.stringify({theme:theme.value,blocks:blocks});document.getElementById('studio-fields-json').value=JSON.stringify(fields)});render();
})();
</script>
